import React from "react";
import LoginLayout from "./LoginLayout";
import {forgetPassword} from "../services/AuthApi";
import axios from "axios";

export default function ForgetPassword() {
    function handleSubmit(user) {
        axios.post('http://localhost:8000/api/forgetpassword', {username: user.username})
            .then(() => {
                alert('Password recovery email has been sent to your email');
            })
            .catch((e) => {
                alert('error');
                console.log(e);
            });
    }

    return (
        <LoginLayout
            title={`Forget Password`}
            handleOnSubmit={handleSubmit}
            linkHref={`/signup`}
            submitText={`Password Recovery`}
            label={`Sign up`}
            flag={false}
            linkHref2={'/'}
            label2={'Sign In'}
        />
    );
}
